import asyncio
import atexit
import sys
import types

NS = types.SimpleNamespace


def read_doc(path):
    return f"-- contents of {path}"


def render_review(incident_id):
    return f"Run a blameless review of {incident_id}: timeline, impact, causes."


async def _restart(name):
    return f"worker {name} restarted"


ops_api = NS(restart=_restart)


class _MCPServer:
    def __init__(self, name):
        self.name = name
        self.tools, self.resources, self.prompts = {}, {}, {}

    def tool(self):
        def register(fn):
            self.tools[fn.__name__] = fn
            return fn
        return register

    def resource(self, uri):
        def register(fn):
            self.resources[uri] = fn
            return fn
        return register

    def prompt(self):
        def register(fn):
            self.prompts[fn.__name__] = fn
            return fn
        return register

    def run(self, transport="stdio"):
        print(f"{self.name}: serving MCP over {transport}")


_servers = []


def _make(name):
    server = _MCPServer(name)
    _servers.append(server)
    return server


@atexit.register
def _report():
    for s in _servers:
        print("tools:", sorted(s.tools), "| resources:", sorted(s.resources),
              "| prompts:", sorted(s.prompts))
        for fn in s.tools.values():
            if asyncio.iscoroutinefunction(fn):
                print(asyncio.run(fn("emails")))


sys.modules["mcp"] = types.ModuleType("mcp")
sys.modules["mcp.server"] = NS(MCPServer=_make)
